package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@RestController @RequestMapping("/api/stores/{storeId}/template") public class StoreTemplateController {
 private final StoreAccess access;private final StoreTemplateRepository templates;private final StockBatchService locks;private final StoreTaskRepository tasks;
 public StoreTemplateController(StoreAccess access,StoreTemplateRepository templates,StockBatchService locks,StoreTaskRepository tasks){this.access=access;this.templates=templates;this.locks=locks;this.tasks=tasks;}
 public record Template(String industry,boolean expiryEnabled,List<String> categories,List<String> examples,long revision){}
 public record Save(String industry,boolean expiryEnabled,List<String> categories,List<String> examples,long revision,boolean createExamples){}
 static Template preset(String name){return switch(name==null?"":name){case "카페"->new Template(name,true,List.of("원두","우유·음료","디저트","소모품"),List.of("커피 머신 청소","우유 유통기한 확인","테이블 정리"),0);case "만화카페"->new Template(name,true,List.of("도서","식음료","소모품"),List.of("도서 정리","좌석 정리","식음료 재고 확인"),0);case "음식점"->new Template(name,true,List.of("식재료","냉장·냉동","음료","소모품"),List.of("식재료 유통기한 확인","주방 위생 점검","마감 청소"),0);case "화장품"->new Template(name,true,List.of("스킨케어","메이크업","클렌징","헤어·바디","소품"),List.of("테스터 위생 점검","진열대 정리","사용기한 확인"),0);case "의류점"->new Template(name,false,List.of("상의","하의","아우터","신발","액세서리"),List.of("진열 정리","피팅룸 점검"),0);case "소매점"->new Template(name,true,List.of("식품","생활용품","잡화"),List.of("진열대 정리","재고 보충","유통기한 확인"),0);default->new Template("기타",true,List.of("기타"),List.of("매장 정리","비품 점검"),0);};}
 private Template view(StoreTemplate t){return new Template(t.getIndustry(),t.isExpiryEnabled(),List.copyOf(t.getCategories()),List.copyOf(t.getExamples()),t.getRevision());}
 @GetMapping("/presets") public List<Template> presets(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId){access.requireMember(a,storeId);return List.of("카페","만화카페","소매점","음식점","화장품","의류점","기타").stream().map(StoreTemplateController::preset).toList();}
 @GetMapping @Transactional(readOnly=true) public Template get(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId){Store s=access.requireMember(a,storeId);return templates.findById(storeId).map(this::view).orElse(preset(s.getType()));}
 @PutMapping @Transactional public Template save(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@RequestBody Save r){Store s=access.requireOwner(a,storeId);locks.lock(s);if(!Set.of("카페","만화카페","소매점","음식점","화장품","의류점","기타").contains(r.industry()==null?"":r.industry())||r.categories()==null||r.categories().size()>20||r.examples()==null||r.examples().size()>20||r.categories().stream().anyMatch(x->x==null||x.isBlank()||x.length()>30)||r.examples().stream().anyMatch(x->x==null||x.isBlank()||x.length()>100))throw new ApiException(HttpStatus.BAD_REQUEST,"업종·분류·기본 업무를 확인해주세요");var t=templates.findById(storeId).orElseGet(()->new StoreTemplate(storeId));if(t.getRevision()!=r.revision())throw new ApiException(HttpStatus.CONFLICT,"템플릿이 변경됐어요. 다시 불러와주세요");t.update(r.industry(),r.expiryEnabled(),r.categories().stream().map(String::trim).distinct().toList(),r.examples().stream().map(String::trim).distinct().toList());templates.save(t);if(r.createExamples())for(String title:t.getExamples()){String key="template-"+r.industry()+"-"+Integer.toUnsignedString(title.hashCode());if(tasks.findByStoreAndClientKey(s,key).isEmpty())tasks.save(new StoreTask(s,a,key,title,"업종 템플릿 기본 업무",false,null));}return view(t);}
}
